import React from "react";
import { Link } from "react-router-dom";

function Navbar() {
  return (
    <nav className="navbar">

      <div className="logo">🌊 Garbage Detection</div>

      <div className="nav-links">
        <Link to="/">Home</Link>
        <Link to="/">Upload</Link>
        <Link to="/about">About</Link>
      </div>

    </nav>
  );
}

export default Navbar;
